90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
113	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
114	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
120	        HttpHeaders headers = new HttpHeaders();
121	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
122	        String address = normalizeAddress(owner.getAddress());
123	        if (address.isEmpty()) {
124	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
125	        }
126	        owner.setAddress(address);
127	        if (owner.getEmail() != null) {
128	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
129	            if (!EMAIL_PATTERN.matcher(email).matches()) {
130	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
131	            }
132	            owner.setEmail(email);
133	        }
134	        if (!isPostcodeValidForCity(owner)) {
135	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
136	        }
137	        String telephone = normalizeTelephone(owner.getTelephone());
138	        if (telephone == null) {
139	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
140	        }
141	        owner.setTelephone(telephone);
142	        LocalDate suppliedRegistrationDate = owner.getRegistrationDate();
143	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
144	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
145	        }
146	        LocalDate registrationDate = resolveRegistrationDate(suppliedRegistrationDate);
147	        owner.setRegistrationDate(registrationDate);
148	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
149	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
150	        }
151	        owner.setIdentityKey(identityKey(owner));
152	        if (isDuplicate(owner)) {
153	            return new ResponseEntity<>(HttpStatus.CONFLICT);
154	        }
155	        if (countOwnersInCity(owner.getCity()) >= 50) {
156	            return new ResponseEntity<>(HttpStatus.CONFLICT);
157	        }
158	        assignRegistrationAttributes(owner);
159	        this.clinicService.saveOwner(owner);
160	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={}",
161	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
162	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
163	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
164	        headers.setLocation(UriComponentsBuilder.newInstance()
165	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
166	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
167	    }
